 "content": "from collections import Counter


def transform(grid):
    """Encode the number of horizontal colored bars as color-count cells."""
    background = Counter(value for row in grid for value in row).most_common(1)[0][0]
    counts = Counter()
    for row in grid:
        col = 0
        while col < len(row):
            color = row[col]
            if color == background:
                col += 1
                continue
            counts[color] += 1
            while col < len(row) and row[col] == color:
                col += 1
    # The output is a 2x3 tally, with colors represented in descending order.
    tally = []
    for color in sorted(counts, reverse=True):
        tally.extend([color] * counts[color])
    out = [[0] * 3 for _ in range(2)]
    for i, color in enumerate(tally[:6]):
        out[i // 3][i % 3] = color
    return out


